<section class="card" aria-live="polite"><div class="flex items-center justify-between"><div><h2 class="text-lg font-bold">Orientační náhled</h2><p class="mt-1 text-sm text-slate-600">Finální částky vždy znovu vypočítá server při uložení.</p></div><button class="button-secondary" type="button" @click="refreshPreview">Přepočítat</button></div>
    <p class="mt-4 text-sm text-slate-500" x-show="loading">Počítám…</p><p class="mt-4 text-sm text-red-700" x-show="previewError" x-text="previewError"></p>
    <dl class="mt-4 grid gap-3 text-sm sm:grid-cols-2 xl:grid-cols-4" x-show="preview"><div><dt class="text-slate-500">Základ</dt><dd class="font-semibold" x-text="money(preview?.totals?.tax_base_total)"></dd></div><div><dt class="text-slate-500">DPH</dt><dd class="font-semibold" x-text="money(preview?.totals?.vat_total)"></dd></div><div><dt class="text-slate-500">Zaokrouhlení</dt><dd class="font-semibold" x-text="money(preview?.totals?.rounding_adjustment)"></dd></div><div><dt class="text-slate-500">Celkem</dt><dd class="text-lg font-bold" x-text="`${money(preview?.totals?.grand_total)} ${currency}`"></dd></div></dl>
</section>
